"""Ilustrações da tela de resposta da lição (Correto! / Ops...), recortadas da imagem de referência enviada pelo Gabriel.
Cada item: (WebP em base64, largura, altura). Módulo só de dados: nada de pasta de imagens para subir."""
from __future__ import annotations

BANNERS = {
    "ok": ("", 601, 341),
    "err": ("", 593, 341),
}


def uri(nome: str) -> str:
    return "data:image/webp;base64," + BANNERS[nome][0]


def proporcao(nome: str) -> float:
    """altura/largura, para reservar o espaço antes de a imagem carregar."""
    return BANNERS[nome][2] / BANNERS[nome][1]
